private void permute(int[] nums, int index, List<List<Integer>> permutations) {
    if (index == nums.length - 1) {
        permutations.add(new ArrayList<Integer>(nums));
        return;
    }
    for (int i = index; i < nums.length; i++) {
        swap(nums, index, i);
        permute(nums, index + 1, permutations);
        swap(nums, index, i);
    }
}

