private static double calculateMean(int[] arr) {
    double sum = 0.0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    return sum / arr.length;
}

private static double calculateTrimmedMean(int[] arr, double lowerPercentile, double upperPercentile) {
    // Check if the percentiles are valid
    if (lowerPercentile < 0 || lowerPercentile > 1 || upperPercentile < 0 || upperPercentile > 1) {
        throw new IllegalArgumentException("Percentiles must be between 0 and 1");
    }

    // Calculate the number of elements to remove from the lower and upper ends of the array
    int lowerElementsToRemove = (int) Math.ceil(lowerPercentile * arr.length);
    int upperElementsToRemove = (int) Math.ceil(upperPercentile * arr.length);

    // Remove the elements from the lower and upper ends of the array
    int[] trimmedArr = arr.clone();
    if (lowerElementsToRemove > 0) {
        trimmedArr = Arrays.copyOfRange(trimmedArr, lowerElementsToRemove, trimmedArr.length - upperElementsToRemove);
    }

    // Calculate the mean of the trimmed array
    double trimmedMean = calculateMean(trimmedArr);

    // Return the trimmed mean
    return trimmedMean;
}

