public int minOperations(int n) {
    // arr is an integer array of length n, where arr[i] = (2 * i) + 1
    // Initialize the minimum number of operations to 0
    int minOperations = 0;

    // Loop through the array and perform operations
    for (int i = 0; i < n; i++) {
        // Find the minimum element in the subarray arr[i..n-1]
        int minElement = arr[i];
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < minElement) {
                minElement = arr[j];
            }
        }

        // Calculate the number of operations required to make all elements in the subarray equal to the minimum element
        int operations = 0;
        for (int j = i; j < n; j++) {
            operations += (arr[j] - minElement);
        }

        // Update the minimum number of operations
        minOperations = Math.max(minOperations, operations);
    }

    return minOperations;
}

