public String makeGood(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    char[] chars = s.toCharArray();
    Set<Character> lowercaseSet = new HashSet<>();
    Set<Character> uppercaseSet = new HashSet<>();

    for (char c : chars) {
        if (Character.isLowerCase(c)) {
            lowercaseSet.add(c);
        } else if (Character.isUpperCase(c)) {
            uppercaseSet.add(c);
        }
    }

    for (char c : lowercaseSet) {
        if (uppercaseSet.contains(Character.toUpperCase(c))) {
            lowercaseSet.remove(c);
            uppercaseSet.remove(Character.toUpperCase(c));
        }
    }

    return new String(chars);
}

public int maxUniqueSplit(String s) {
    // Edge case: If the string is empty or null, return 0
    if (s == null || s.isEmpty()) {
        return 0;
    }

    // Initialize a map to store the unique substrings
    Map<String, Integer> substringCount = new HashMap<>();

    // Initialize the maximum number of unique substrings to 0
    int maxUniqueSubstrings = 0;

    // Loop through the string and split it into substrings
    for (int i = 0; i < s.length(); i++) {
        String substring = s.substring(i);

        // If the substring is already in the map, increment its count
        if (substringCount.containsKey(substring)) {
            substringCount.put(substring, substringCount.get(substring) + 1);
        } else {
            // If the substring is not in the map, add it to the map with a count of 1
            substringCount.put(substring, 1);
        }

        // If the substring count is equal to the maximum number of unique substrings,
        // update the maximum number of unique substrings
        if (substringCount.get(substring) == maxUniqueSubstrings) {
            maxUniqueSubstrings++;
        }
    }

    return maxUniqueSubstrings;
}

