public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                while (i + currentLength < mat.length && j + currentLength < mat[i].length && mat[i + currentLength][j + currentLength] == 1) {
                    currentLength++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

public static String addThousandSeparator(int n) {
    String strN = String.valueOf(n);
    StringBuilder result = new StringBuilder();
    for (int i = strN.length() - 1, count = 1; i >= 0; i--, count++) {
        result.append(strN.charAt(i));
        if (count % 3 == 0 && i != 0) {
            result.append('.');
        }
    }
    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (A[i] < 0) {
            throw new IllegalArgumentException("The input array must be non-negative.");
        }
    }
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (isPerfectSquare(sum)) {
            count++;
        }
    }
    return count;
}

private static boolean isPerfectSquare(int x) {
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int minHeight = heights[0];
    int maxHeight = heights[0];
    int currentWidth = 1;

    for (int i = 1; i < heights.length; i++) {
        if (heights[i] < minHeight) {
            minHeight = heights[i];
        } else if (heights[i] > maxHeight) {
            maxHeight = heights[i];
        }

        currentWidth++;

        int area = (maxHeight - minHeight) * currentWidth;
        if (area > maxArea) {
            maxArea = area;
        }
    }

    return maxArea;
}

