public static int findSmallestInteger(int n) {
  if (n <= 0) {
    throw new IllegalArgumentException("n must be a positive integer");
  }

  // Convert the integer to a string
  String str = String.valueOf(n);

  // Sort the string digits
  char[] digits = str.toCharArray();
  Arrays.sort(digits);

  // Convert the sorted digits back to a string
  String sortedStr = new String(digits);

  // Convert the string back to an integer
  int result = Integer.parseInt(sortedStr);

  // Return the result if it is greater than the input, otherwise return -1
  return result > n ? result : -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    // Initialize an empty list to store the results
    List<String> list = new ArrayList<>();

    // Loop through all possible combinations of digits
    for (int i = 0; i < 10; i++) {
        // Check if the number is center symmetric
        if (isCenterSymmetric(i, n)) {
            // If it is, add it to the list
            list.add(String.valueOf(i));
        }
    }

    return list;
}

private static boolean isCenterSymmetric(int num, int n) {
    // Check if the number is a digit
    if (num >= 0 && num <= 9) {
        // Check if the number is center symmetric
        if (num == (num * 10 + num) % 10) {
            return true;
        }
    }
    return false;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the slopes of the lines
    double slope1 = (double) (y2 - y1) / (x2 - x1);
    double slope2 = (double) (y3 - y2) / (x3 - x2);

    // Check if the slopes are the same
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points are on the same line
    if (y1 - y2 == slope1 * (x1 - x2)) {
        return false;
    }

    // Check if the points are on the same line
    if (y2 - y3 == slope2 * (x2 - x3)) {
        return false;
    }

    // Check if the triange is a boomerang
    if (slope1 * (x3 - x1) == y3 - y1 && slope2 * (x3 - x2) == y3 - y2) {
        return true;
    }

    return false;
}

public static int findNthUglyNumber(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        List<Integer> uglyNumbers = new ArrayList<>();
        uglyNumbers.add(1);
        int i = 0;
        int j = 0;
        int k = 0;

        while (uglyNumbers.size() < n) {
            int nextUglyNumber = Math.min(uglyNumbers.get(i) * 2, Math.min(uglyNumbers.get(j) * 3, uglyNumbers.get(k) * 5));
            uglyNumbers.add(nextUglyNumber);

            if (uglyNumbers.get(i) * 2 == nextUglyNumber) {
                i++;
            }
            if (uglyNumbers.get(j) * 3 == nextUglyNumber) {
                j++;
            }
            if (uglyNumbers.get(k) * 5 == nextUglyNumber) {
                k++;
            }
        }

        return uglyNumbers.get(n - 1);
    }

public static int calculateEnergy(String s) {
        int max_len = 0;
        int[] char_count = new int[26]; // count of each character.
        char last_char = '?'; // last character seen.
        int last_char_count = 0; //count of last char seen.
        for (int i=0; i < s.length(); i++) {
            char curr_char = s.charAt(i);
            if (curr_char != last_char) {
                char_count[curr_char - 'a']++;
                if (last_char != '\0')
                    char_count[last_char - 'a'] = last_char_count;
                last_char = curr_char;
                last_char_count = 1;
            } else {
                last_char_count++;
            }
        }
        for (int i=0; i < 26; i++)
            if (char_count[i] > max_len)
                max_len = char_count[i];
        return max_len;
    }

