public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("The input array cannot be null");
    }
    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    int sum = 0;
    for (int element : uniqueElements) {
        sum += element;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int count = minPerfectSquareSum(n - i * i);
        if (count < minSquares) {
            minSquares = count;
        }
    }
    return minSquares;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
      return s;
    }
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
      sb.append(new StringBuilder(word).reverse().toString()).append(" ");
    }
    return sb.toString().trim();
}
